import json

# Check 1999 bulletin for 2025
with open('/app/resources/treasury_bulletin_1999_06.json') as f:
    data = json.load(f)

# Search recursively for 2025
def find_2025(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}'
            if '2025' in str(k) or '2025' in str(v):
                results.append((new_path, str(v)[:200]))
            results.extend(find_2025(v, new_path))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_2025(v, f'{path}[{i}]'))
    return results

results = find_2025(data)
for path, val in results[:10]:
    print(f'{path}: {val[:100]}')
"
